"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["54791"],{80835(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>u,frontMatter:()=>i,contentTitle:()=>r,toc:()=>l,assets:()=>h});var o=JSON.parse('{"id":"qiangguo/chzhshchtoty","title":"","description":"Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n 2006-07-28","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/chzhshchtoty.md","sourceDirName":"qiangguo","slug":"/qiangguo/chzhshchtoty","permalink":"/en/qiangguo/chzhshchtoty","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"chzhshchtoty","title":"","hide_table_of_contents":true,"sidebar_label":"Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n\'s reply to Tang Yao ID\'s reply"},"sidebar":"qiangguoSidebar","previous":{"title":"Strange \u2014 why can\'t Gao Tianhu be suspected of perjury?","permalink":"/en/qiangguo/gthperjury"},"next":{"title":"\u96BE\u9053\u7F51\u7EDC\u5DE6\u6D3E\u90FD\u7531\u4E00\u7FA4\u4E0D\u5B66\u65E0\u672F\u8005\u7EC4\u6210\uFF1F","permalink":"/en/qiangguo/thenetworkleft"}}'),a=n(74848),s=n(28453);let i={id:"chzhshchtoty",title:"",hide_table_of_contents:!0,sidebar_label:"Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n's reply to Tang Yao ID's reply"},r="Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n's Reply to Tang Yao ID's Reply",h={},l=[];function d(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"ch\xe1n-zh\u014Dng-shu\u014D-ch\xe1ns-reply-to-tang-yao-ids-reply",children:"Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n's Reply to Tang Yao ID's Reply"})}),"\n",(0,a.jsxs)(t.blockquote,{children:["\n",(0,a.jsx)(t.p,{children:"Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n 2006-07-28"}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Tang Yao ID replied today to this ID's post \"Tang Yao, who understands neither Confucianism nor Buddhism \u2014 don't frame Buddhism with the Confucian concept of 'Human nature is self-endowed, Buddha-nature is humanly achieved'!\" It seems the biggest accusation is that this ID has a bad attitude. But this ID is not a fan of that former Yugoslav football coach, and has no interest in the nonsense of \"attitude determines everything.\""}),"\n",(0,a.jsx)(t.p,{children:'As for the question of what constitutes framing, Tang ID seems to think that "human nature is self-endowed, Buddha-nature is humanly achieved" is too good a statement to count as framing. But so-called "good" is relative \u2014 what seems good at one level of understanding may be nothing at all. "Good" is a value judgment; "framing" is an act \u2014 the two don\'t connect. Furthermore, if Tang ID insists that it only counts as framing if it\'s written in black and white as "human nature is self-endowed, Confucian-nature is humanly achieved," then as long as the one doing the framing doesn\'t tattoo the words "I\'m framing" on their face, there\'s no framing \u2014 in which case, courts should just hire fortune tellers. As for what this ID "understands" \u2014 you bring up "Let the mind arise without dwelling anywhere." So what does this mind understand? And what doesn\'t it understand? What does it give rise to? And what doesn\'t it give rise to?'}),"\n",(0,a.jsx)(t.p,{children:'Additionally, Tang ID brought up Mao Zedong\'s "universalization of education, integration of study and application, popularization of philosophy." These don\'t seem to be Mao Zedong\'s original ideas \u2014 they\'re merely restatements of things said by predecessors. Moreover, on the relationship between knowledge and action, some of Mao Zedong\'s ideas are still far from thorough understanding, probably all caused by this pseudo-proposition of "popularization of philosophy." Even from the perspective of Chinese cultural tradition \u2014 mind is principle, pertaining to every person\'s body and mind, present in every moment \u2014 what need is there for a pseudo-proposition like "popularization of philosophy"? Philosophy that can be popularized is nothing but pseudo-philosophy. True philosophy has never been apart from the masses in the first place \u2014 what is there to "popularize"?'}),"\n",(0,a.jsx)(t.p,{children:"Since this reply has far too little technical content, making it hard for this ID's response to even fill 500 words, I'll end with some words not directed at any particular ID but for everyone's mutual encouragement: 1. Everyone must die. 2. Dead people are no longer people. 3. No one should be a secondhand hearer who swallows everything uncritically. 4. Every person is a Yao or Shun \u2014 they just stifle themselves. 5. Don't be a spittle-swallower. Everyone has a brain and a tongue \u2014 make your own voice heard, instead of turning yourself into a parrot."})]})}function u(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>i,x:()=>r});var o=n(96540);let a={},s=o.createContext(a);function i(e){let t=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);